import Lenis from 'lenis';

window.scrollTo(0, 0);
const lenis = new Lenis({ smoothWheel: true });
function raf(t){ lenis.raf(t); requestAnimationFrame(raf); }
requestAnimationFrame(raf);

/* ---------------- Adaptive grid scale-up ---------------- */
function applyAdaptiveGrid(){
  const FONT_BASE = 16, baseWidth = 1920, coef = 0.6666;
  const w = window.innerWidth;
  const widthReduction = ((baseWidth - w) / baseWidth) * 100;
  const size = FONT_BASE - (FONT_BASE * (widthReduction * coef)) / 100;
  if (size > FONT_BASE) document.documentElement.style.fontSize = size + 'px';
  else document.documentElement.style.removeProperty('font-size');
}
applyAdaptiveGrid();
window.addEventListener('resize', applyAdaptiveGrid);

/* ---------------- Scroll lock model ---------------- */
let scrollEnabled = true;
function stopScroll(){
  scrollEnabled = false;
  lenis.stop();
  document.documentElement.classList.add('no-scroll');
}
function startScroll(){
  scrollEnabled = true;
  lenis.start();
  document.documentElement.classList.remove('no-scroll');
}

function scrollToId(id){
  const el = document.getElementById(id);
  if (!el) return;
  const wasEnabled = scrollEnabled;
  scrollEnabled = false;
  setTimeout(() => {
    const top = el.getBoundingClientRect().top + window.pageYOffset;
    window.scrollTo({ top, behavior: 'smooth' });
  }, 50);
  setTimeout(() => { scrollEnabled = wasEnabled; }, 100);
}

document.querySelectorAll('[data-scroll]').forEach(btn => {
  btn.addEventListener('click', (e) => {
    e.preventDefault();
    const id = btn.getAttribute('data-scroll');
    closeMenu();
    scrollToId(id);
  });
});

/* ---------------- Loader ---------------- */
const loaderEl = document.getElementById('loader');
const loaderFill = document.getElementById('loader-fill');
const loaderNum = document.getElementById('loader-num');
let introReady = false;

stopScroll();

function easeInOutCubic(t){
  return t < 0.5 ? 4*t*t*t : 1 - Math.pow(-2*t+2, 3)/2;
}

const FILL_MS = 1300;
const loaderStart = performance.now();
function loaderTick(now){
  const t = Math.min((now - loaderStart) / FILL_MS, 1);
  const eased = easeInOutCubic(t);
  const progress = Math.round(eased * 100);
  loaderFill.style.width = progress + '%';
  loaderNum.textContent = String(progress).padStart(3, '0');
  if (t < 1) {
    requestAnimationFrame(loaderTick);
  } else {
    setTimeout(() => {
      loaderEl.classList.add('exit');
      setTimeout(() => {
        introReady = true;
        startScroll();
        loaderEl.remove();
        document.dispatchEvent(new Event('intro-ready'));
      }, 700);
    }, 150);
  }
}
requestAnimationFrame(loaderTick);

/* ---------------- Reveal system ---------------- */
function runReveal(el){
  const delay = parseInt(el.getAttribute('data-delay') || '0', 10);
  setTimeout(() => el.classList.add('in'), delay);
}

function runLineReveal(el){
  const delay = parseInt(el.getAttribute('data-line-delay') || '0', 10);
  const stagger = parseInt(el.getAttribute('data-line-stagger') || '0', 10);
  setTimeout(() => el.classList.add('in'), delay + stagger);
}

function splitWords(el){
  const text = el.textContent;
  el.textContent = '';
  const words = text.trim().split(/\s+/);
  words.forEach((w, i) => {
    const span = document.createElement('span');
    span.className = 'word';
    span.textContent = w;
    span.style.transitionDelay = (i * 35) + 'ms';
    el.appendChild(span);
    if (i < words.length - 1) el.appendChild(document.createTextNode(' '));
  });
}

/* About H2 with mixed color spans -> word split manually preserving muted span */
const aboutH2 = document.getElementById('about-h2');
(function buildAboutH2(){
  const part1 = "Saya lulusan Teknik Informatika yang senang mengubah ide jadi web yang benar-benar jalan — dari HTML, PHP, sampai database MySQL, ";
  const part2 = "dengan pengalaman nyata di jaringan komputer, produksi konten digital bersertifikasi BNSP, serta kebiasaan kerja teliti dan cepat beradaptasi.";
  const frag = document.createDocumentFragment();
  let wordIndex = 0;
  function addWords(text, muted){
    const words = text.trim().split(/\s+/);
    words.forEach((w) => {
      const span = document.createElement('span');
      span.className = 'word';
      if (muted) span.style.color = '#8d8d8d';
      span.textContent = w;
      span.style.transitionDelay = (wordIndex * 35) + 'ms';
      frag.appendChild(span);
      frag.appendChild(document.createTextNode(' '));
      wordIndex++;
    });
  }
  addWords(part1, false);
  addWords(part2, true);
  aboutH2.appendChild(frag);
})();

const io = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      const el = entry.target;
      if (el.classList.contains('line-wrap')) runLineReveal(el);
      else if (el.classList.contains('word-container')) {
        el.querySelectorAll('.word').forEach(w => w.classList.add('in'));
      } else runReveal(el);
      io.unobserve(el);
    }
  });
}, { threshold: 0.15 });

document.querySelectorAll('.reveal, .line-wrap').forEach(el => io.observe(el));

// about h2 words reveal as a group once container visible
const aboutWordIO = new IntersectionObserver((entries) => {
  entries.forEach(entry => {
    if (entry.isIntersecting) {
      aboutH2.querySelectorAll('.word').forEach(w => w.classList.add('in'));
      aboutWordIO.unobserve(entry.target);
    }
  });
}, { threshold: 0.15 });
aboutWordIO.observe(aboutH2);

